+        if (persistentState.TryTakeFromJson<List<ClaimData>>(nameof(ClaimData), out var claimData) && claimData is not null)
+        {
+            var claims = claimData.Select(c => new Claim(c.Type, c.Value)).ToList();
+            var identity = new ClaimsIdentity(claims, "Hardcoded");
+            var principal = new ClaimsPrincipal(identity);
+            _authState = Task.FromResult(new AuthenticationState(principal));
+        }
+        else
+        {
+            _authState = _unauthenticated;
+        }
+    }
+
+    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authState;
+}
+
+public sealed record ClaimData(string Type, string Value);
